\set ON_ERROR_STOP on
BEGIN;
CREATE TEMP TABLE preview_preserved AS SELECT(SELECT jsonb_agg(to_jsonb(c)ORDER BY id)FROM public.customers c)customers,(SELECT jsonb_agg(to_jsonb(o)ORDER BY id)FROM public.orders o)orders;
INSERT INTO private.kinto_deletion_requests_v1(id,customer_id,status,verified_by)VALUES('00000000-0000-4000-8000-000000000091','00000000-0000-4000-8000-000000000001','verified','00000000-0000-4000-8000-000000000099');
SELECT public.test_denied($q$SELECT public.kinto_privacy_transaction_preview_admin_v1('test-TEST-A','00000000-0000-4000-8000-000000000091')$q$,'ADMIN_SESSION_INVALID');
SELECT public.test_denied($q$SELECT public.kinto_privacy_transaction_preview_admin_v1('invalid','00000000-0000-4000-8000-000000000091')$q$,'ADMIN_SESSION_INVALID');
SELECT public.test_denied($q$SELECT public.kinto_privacy_transaction_preview_admin_v1('test-admin','00000000-0000-4000-8000-000000000092')$q$,'VERIFIED_REQUEST_REQUIRED');
SET ROLE anon;
SELECT public.test_assert(public.kinto_privacy_transaction_preview_admin_v1('test-admin','00000000-0000-4000-8000-000000000091')->'sections'->'orders'->>'sample_count'='0','customer B order excluded from A preview');
SELECT public.test_assert(NOT has_function_privilege('anon','private.kinto_privacy_transaction_preview_v1(uuid)','EXECUTE'),'no direct private helper access');
RESET ROLE;
SELECT public.test_assert(public.kinto_privacy_transaction_preview_admin_v1('test-admin','00000000-0000-4000-8000-000000000091')->'sections'->'world_orders'->>'available'='false','missing observed tables are unavailable not empty');
SAVEPOINT preview_fixture;
ALTER TABLE public.orders DROP CONSTRAINT orders_customer_id_fkey;
ALTER TABLE public.orders ALTER COLUMN customer_id TYPE text USING customer_id::text;
ALTER TABLE public.orders ALTER COLUMN details TYPE text USING details::text;
ALTER TABLE public.order_store_segments ADD COLUMN customer_snapshot jsonb;
INSERT INTO public.orders(id,customer_id,status,details)VALUES('00000000-0000-4000-8000-000000000093','00000000-0000-4000-8000-000000000001','unchanged','{bad');
INSERT INTO public.order_store_segments(id,order_id,customer_snapshot)VALUES('00000000-0000-4000-8000-000000000094','00000000-0000-4000-8000-000000000093','{"name":"PRIVATE_SYNTHETIC"}');
CREATE TABLE private.kinto_payment_attempts_p4(id uuid PRIMARY KEY,customer_id text,status text,expires_at timestamptz);
INSERT INTO private.kinto_payment_attempts_p4 VALUES('00000000-0000-4000-8000-000000000095','00000000-0000-4000-8000-000000000001','pending',now()-interval '10 days');
CREATE TABLE private.kinto_world_orders_v1(id uuid PRIMARY KEY,customer_id uuid,request jsonb);
INSERT INTO private.kinto_world_orders_v1 VALUES('00000000-0000-4000-8000-000000000096','00000000-0000-4000-8000-000000000001','{"contact":{"phone":"PRIVATE_PHONE"}}');
CREATE TEMP TABLE preview_result AS SELECT public.kinto_privacy_transaction_preview_admin_v1('test-admin','00000000-0000-4000-8000-000000000091')r;
SELECT public.test_assert((SELECT r->'sections'->'orders'->>'sample_count'='1'AND r->'sections'->'orders'->>'unreadable_objects'='1'FROM preview_result),'observed TEXT ownership and malformed details detected');
SELECT public.test_assert((SELECT r->'sections'->'segments'->>'sample_count'='1'AND r->'sections'->'segments'->>'invoice_dependency_review_required'='true'FROM preview_result),'segment linked by order only; nonempty snapshot never proves complete');
SELECT public.test_assert((SELECT r->'sections'->'payment_attempts'->>'outcome_unresolved'='1'FROM preview_result),'pending beyond expiry stays unresolved');
SELECT public.test_assert((SELECT r->>'deletion_authorized'='false'AND r->>'coverage_complete'='false'AND r->>'production_ready'='false'FROM preview_result),'preview has no erasure or coverage authority');
SELECT public.test_assert((SELECT r::text NOT LIKE '%PRIVATE_%'AND r::text NOT LIKE '%00000000-%'FROM preview_result),'no contact, row/customer IDs or raw details in report');
INSERT INTO private.kinto_world_orders_v1 SELECT md5(g::text)::uuid,'00000000-0000-4000-8000-000000000001','{}'FROM generate_series(1,205)g;
SELECT public.test_assert(public.kinto_privacy_transaction_preview_admin_v1('test-admin','00000000-0000-4000-8000-000000000091')->'sections'->'world_orders'->>'sample_count'='200'AND public.kinto_privacy_transaction_preview_admin_v1('test-admin','00000000-0000-4000-8000-000000000091')->'sections'->'world_orders'->>'truncated'='true','sample capped and overflow explicit');
SAVEPOINT schema_drift;
ALTER TABLE private.kinto_world_orders_v1 ALTER COLUMN customer_id TYPE text;
SELECT public.test_assert(public.kinto_privacy_transaction_preview_admin_v1('test-admin','00000000-0000-4000-8000-000000000091')->'sections'->'world_orders'->>'available'='false','unexpected column type is not silently accepted');
ROLLBACK TO schema_drift;
CREATE ROLE preview_limited;
GRANT USAGE ON SCHEMA public TO preview_limited;
GRANT USAGE,CREATE ON SCHEMA private TO preview_limited;
GRANT SELECT ON private.kinto_world_orders_v1 TO preview_limited;
ALTER TABLE private.kinto_world_orders_v1 ENABLE ROW LEVEL SECURITY;
ALTER FUNCTION private.kinto_privacy_preview_relation_v1(text,jsonb)OWNER TO preview_limited;
SELECT public.test_assert(NOT private.kinto_privacy_preview_relation_v1('private.kinto_world_orders_v1','{"id":["uuid"]}'),'hidden RLS rows cannot be represented as zero');
ALTER FUNCTION private.kinto_privacy_preview_relation_v1(text,jsonb)OWNER TO postgres;
UPDATE private.kinto_deletion_requests_v1 SET status='manual_review'WHERE id='00000000-0000-4000-8000-000000000091';
SELECT public.test_denied($q$SELECT public.kinto_privacy_transaction_preview_admin_v1('test-admin','00000000-0000-4000-8000-000000000091')$q$,'VERIFIED_REQUEST_REQUIRED');
ROLLBACK TO preview_fixture;
SELECT public.test_assert((SELECT customers FROM preview_preserved)=(SELECT jsonb_agg(to_jsonb(c)ORDER BY id)FROM public.customers c),'all customer profiles preserved');
SELECT public.test_assert((SELECT orders FROM preview_preserved)=(SELECT jsonb_agg(to_jsonb(o)ORDER BY id)FROM public.orders o),'all original orders preserved');
ROLLBACK;
SELECT 'PASS_TRANSACTION_PREVIEW: exact verified-admin scope, observed TEXT types, bounded samples, private output, missing/schema/RLS holds, unresolved payment and no deletion authority';
